// Тикет #36a75b77 (36a75b778027ed97e0a701ec) — принят 18.10.2026 (עבר QA, TestFlight 1.0.0 (20) + OTA, commit 607022e).
// Был @known-bug (реджект 14.10 rej_e23a96637d6aedcc5bb477ad: после свайпа 'סגירה' y=28, visible=false) — снят 18.10.
// «מה רצוי» #36a75b77: верх окна «עריכת תאריך» — ниже строки статуса (Safe Area); заголовок и «×» не перекрываются
//   временем/сигналом/батареей; «×» удобно нажимается.
// Факт 18.10 (3/3): при открытии и после свайпа ВНУТРИ окна (200,650 → 200,300) 'סגירה' y=95, visible=true;
//   «×» и «שמירת השינויים» работают после прокрутки. Тест проверяет «×» после прокрутки (без возврата прокрутки);
//   «שמירת השינויים» не нажимается — запись клиента не меняем.
// Кейс: .qa/tests/important-dates/ID-08-edit-window-statusbar-scroll.md.
// Запись: «בדיקת QA» (есть у клиента) — только открыть/закрыть (ничего не сохраняется). Нет её на аккаунте —
//   временная «QA-AUTO-סטטוס-NNNN» на сегодня (@data), удаляется в after.
// ПРАВИЛО 14.10: нажатия только по accessibility name; свайп — в средней части экрана (внутри окна).
import { driver, expect } from '@wdio/globals';
import { byText, byLabel, swipeUp } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown } from '../_lib/app-0710.ts';
import { rectOf, staticText, statusBarHeight } from '../_lib/app-1310.ts';
import { homeDates, scrollToDateCard, tryDeleteDate } from '../_lib/app-1310b.ts';
import { addImportantDateToday } from '../_lib/app-1410.ts';
import { isoDate } from '../../../e2e/tests/_helpers/dates.ts';

const CLIENT_DATE = 'בדיקת QA';
const TEMP = `QA-AUTO-סטטוס-${String(Date.now()).slice(-4)}`;
const TITLE = 'עריכת תאריך';
const STATUS_BAR_FALLBACK = 62;   // iPhone 17 (Dynamic Island), факт 14.10
const SHOT = new URL('../../runs/36a75b77-edit-window-scrolled.png', import.meta.url).pathname;
let tempCreated = false;

/** Видимость элемента: iOS — атрибут visible (как в факте 14.10), Android — isDisplayed. */
async function visibleOf(el: WebdriverIO.Element): Promise<boolean> {
  if (!(await el.isExisting().catch(() => false))) return false;
  if (driver.isIOS) return String(await el.getAttribute('visible').catch(() => 'false')) === 'true';
  return el.isDisplayed().catch(() => false);
}

/** Положение и видимость «סגירה» и заголовка окна. Нет элемента — y = -1, visible = false. */
async function header() {
  const close = (await byLabel('סגירה')) as unknown as WebdriverIO.Element;
  let title = (await staticText(TITLE)) as unknown as WebdriverIO.Element;
  if (!(await title.isExisting().catch(() => false))) title = (await byText(TITLE)) as unknown as WebdriverIO.Element;
  const yOf = async (el: WebdriverIO.Element) => ((await el.isExisting().catch(() => false)) ? Math.round((await rectOf(el)).y) : -1);
  return {
    closeY: await yOf(close), closeVisible: await visibleOf(close),
    titleY: await yOf(title), titleVisible: await visibleOf(title),
  };
}

/** Вертикальный свайп внутри окна (точки iOS; на экранах ниже 700 pt — пропорционально). Не тап. */
async function swipeInWindow(fromY: number, toY: number) {
  const { width, height } = await driver.getWindowSize();
  const k = height >= 700 ? 1 : height / 844;
  await driver.action('pointer', { parameters: { pointerType: 'touch' } })
    .move({ x: Math.round(width / 2), y: Math.round(fromY * k) })
    .down().pause(80)
    .move({ duration: 400, x: Math.round(width / 2), y: Math.round(toY * k) })
    .up().perform();
}

/** Дождаться, пока положение шапки перестанет меняться (окончание инерции прокрутки) — без фиксированной паузы. */
async function settledHeader() {
  let prev = await header();
  let cur = prev;
  await driver.waitUntil(async () => {
    cur = await header();
    const same = cur.closeY === prev.closeY && cur.titleY === prev.titleY;
    prev = cur;
    return same;
  }, { timeout: 8000, interval: 500 }).catch(() => {});
  return cur;
}

describe('«תאריכים חשובים»: окно «עריכת תאריך» и строка статуса', () => {
  after(async () => {
    if (tempCreated) {
      try { await tryDeleteDate(TEMP); } catch (e) { console.warn(`[ID-08] удалить «${TEMP}» вручную`, e); }
    }
  });

  it('ID-08 «עריכת תאריך»: после прокрутки внутри окна «סגירה» и заголовок остаются ниже строки статуса (видимы), «סגירה» закрывает окно #36a75b77 @data', async function () {
    // 1. Главная → «תאריכים חשובים» → карандаш записи (по accessibility name).
    await toHome();
    await homeDates();
    let name = CLIENT_DATE;
    let found = false;
    for (let i = 0; i < 6 && !(found = await shown(byLabel(`${CLIENT_DATE}: פתיחה לעריכה`))); i++) await swipeUp();
    if (!found) found = await shown(byLabel(`${CLIENT_DATE}: פתיחה לעריכה`));
    if (!found) {
      name = TEMP;
      await addImportantDateToday(TEMP, isoDate(new Date()));
      tempCreated = true;
    }
    await (await scrollToDateCard(name)).click();
    await (await byText(TITLE)).waitForDisplayed({ timeout: 15000 });

    const sb = (await statusBarHeight()) || STATUS_BAR_FALLBACK;
    console.log(`[ID-08] строка статуса: ${sb} pt; запись «${name}»`);

    try {
      // 2. При открытии (факты 14.10 и 18.10 — ок): «סגירה» ниже строки статуса и видима.
      const open = await settledHeader();
      console.log('[ID-08] при открытии', open);
      expect({ closeBelowStatusBar: open.closeY >= sb, closeVisible: open.closeVisible })
        .toEqual({ closeBelowStatusBar: true, closeVisible: true });

      // 3. Свайп внутри окна (200,650 → 200,300) — шапка окна не должна уезжать под строку статуса.
      await swipeInWindow(650, 300);
      const scrolled = await settledHeader();
      console.log('[ID-08] после свайпа', scrolled, '(факт 18.10: closeY=95, closeVisible=true)');
      await driver.saveScreenshot(SHOT).catch(() => {});
      expect({
        closeBelowStatusBar: scrolled.closeY >= sb, closeVisible: scrolled.closeVisible,
        titleBelowStatusBar: scrolled.titleY >= sb, titleVisible: scrolled.titleVisible,
      }).toEqual({
        closeBelowStatusBar: true, closeVisible: true,
        titleBelowStatusBar: true, titleVisible: true,
      });

      // 4. «סגירה» после прокрутки (без возврата прокрутки) закрывает окно — факт 18.10.
      await (await byLabel('סגירה')).click();
      await expect(byText(TITLE)).not.toBeDisplayed({ wait: 10000 });
    } finally {
      // Страховка: окно осталось открытым (проверка упала) — вернуть прокрутку и закрыть.
      if (await shown(byText(TITLE))) {
        if (!(await header()).closeVisible) await swipeInWindow(300, 650);
        await (await byLabel('סגירה')).click().catch(() => {});
      }
    }
  });
});
